window.CARDS=window.CARDS||{};CARDS["people-nanase-tsubasa"]=[{"i":"sc-nanase-tsubasa-y2v1-p7-1","v":"y2v1","y":2,"o":16,"k":"","w":"tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa prologue  briefed by tsukishiro in a tokyo facility  nanase  unnamed  listens as tsukishiro briefs her on ayanokoji kiyotaka  shows signs of dissatisfaction that ayanokoji is praised as the white room s masterpiece  leaves the room calmly after being asked whether she is hiding something  is briefed and sent to the school  is ordered to help expel him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p7-1\"><h3><span class=\"ttl\">Prologue: Briefed by Tsukishiro<\/span><span class=\"meta\">Y2V1 · p.7–11<\/span><\/h3><p class=\"setup\">In a Tokyo facility, Nanase (unnamed) listens as Tsukishiro briefs her on Ayanokōji Kiyotaka. Shows signs of dissatisfaction that Ayanokōji is praised as the White Room’s masterpiece. Leaves the room calmly after being asked whether she is hiding something.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Is briefed and sent to the school.<span class=\"pg\">p.7–11<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is ordered to help expel him.<span class=\"pg\">p.7–11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p7-2\">→ After: Prologue: Briefed by Tsukishiro<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p7-2","v":"y2v1","y":2,"o":16,"k":"","w":"tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa prologue  briefed by tsukishiro in a tokyo facility  nanase  unnamed  listens as tsukishiro briefs her on ayanokoji kiyotaka  shows signs of dissatisfaction that ayanokoji is praised as the white room s masterpiece  leaves the room calmly after being asked whether she is hiding something  is briefed and sent to the school  is ordered to help expel him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p7-2\"><h3><span class=\"ttl\">Prologue: Briefed by Tsukishiro<\/span><span class=\"meta\">Y2V1 · p.7–11<\/span><\/h3><p class=\"setup\">In a Tokyo facility, Nanase (unnamed) listens as Tsukishiro briefs her on Ayanokōji Kiyotaka. Shows signs of dissatisfaction that Ayanokōji is praised as the White Room’s masterpiece. Leaves the room calmly after being asked whether she is hiding something.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Is briefed and sent to the school.<span class=\"pg\">p.7–11<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is ordered to help expel him.<span class=\"pg\">p.7–11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p7-1\">← Before: Prologue: Briefed by Tsukishiro<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p79-1\">→ After: Ch.3: Class 1-D hallway<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p79-1","v":"y2v1","y":2,"o":16,"k":"","w":"housen-kazuomi ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 3  class 1 d hallway accompanies hosen to class 2 d  stops hosen by referencing  that  apologizes to the second years and bows  looks at ayanokoji before leaving  accompanies and restrains him  looks at him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p79-1\"><h3><span class=\"ttl\">Ch.3: Class 1-D hallway<\/span><span class=\"meta\">Y2V1 · p.79–95<\/span><\/h3><p class=\"setup\">Accompanies Hōsen to Class 2-D. Stops Hōsen by referencing “that”. Apologizes to the second-years and bows. Looks at Ayanokōji before leaving.<\/p><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Accompanies and restrains him.<span class=\"pg\">p.79–95<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Looks at him.<span class=\"pg\">p.95<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p7-2\">← Before: Prologue: Briefed by Tsukishiro<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p100-1\">→ After: Nanase with Hōsen; a probing look at Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p100-1","v":"y2v1","y":2,"o":16,"k":"spoken","w":"ayanokouji-kiyotaka housen-kazuomi nanase-tsubasa","q":"nanase tsubasa nanase with hosen  a probing look at ayanokoji accompanies hosen during his confrontation with ryuen  and obeys his order to withdraw   yes  that s a wise choice   i m sorry for the disturbance  calm and composed beside the volatile hosen   bows a polite final apology on behalf of class 1 d  when she raises her head she fixes ayanokoji with the same inquisitive  probing look as when she first arrived  then quickly looks away and runs after hosen  gives him a knowing  probing look   the white room agent silently assessing her target  obeys his withdrawal order  seen as his second in command in class 1 d","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p100-1\"><h3><span class=\"ttl\">Nanase with Hōsen; a probing look at Ayanokōji<\/span><span class=\"meta\">Y2V1 · p.100–101<\/span><\/h3><p class=\"setup\">Accompanies Hōsen during his confrontation with Ryūen, and obeys his order to withdraw.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Yes. That&#x27;s a wise choice.&quot;<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m sorry for the disturbance.&quot;<span class=\"pg\">p.101<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Calm and composed beside the volatile Hōsen — bows a polite final apology on behalf of Class 1-D; when she raises her head she fixes Ayanokōji with the same inquisitive, probing look as when she first arrived, then quickly looks away and runs after Hōsen.<span class=\"pg\">p.100–101<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Gives him a knowing, probing look — the White Room agent silently assessing her target.<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Obeys his withdrawal order; seen as his second-in-command in Class 1-D.<span class=\"pg\">p.100–101<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p79-1\">← Before: Ch.3: Class 1-D hallway<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p142-1\">→ After: Ch.4: Approaching Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p142-1","v":"y2v1","y":2,"o":16,"k":"","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 4  approaching ayanokoji greets ayanokoji on the way to school  apologizes for hosen s rudeness  discusses cooperation between class 1 d and 2 d  says she will never yield to violence  agrees to set something up for him  approaches and proposes cooperation","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p142-1\"><h3><span class=\"ttl\">Ch.4: Approaching Ayanokōji<\/span><span class=\"meta\">Y2V1 · p.142–155<\/span><\/h3><p class=\"setup\">Greets Ayanokōji on the way to school. Apologizes for Hōsen’s rudeness. Discusses cooperation between Class 1-D and 2-D. Says she will never yield to violence. Agrees to set something up for him.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Approaches and proposes cooperation.<span class=\"pg\">p.148–155<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p100-1\">← Before: Nanase with Hōsen; a probing look at Ayanokōji<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p204-1\">→ After: Ch.5: Library meeting and strategy<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p204-1","v":"y2v1","y":2,"o":16,"k":"","w":"horikita-suzune ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 5  library meeting and strategy meets horikita and ayanokoji in the library  reveals class 1 d s situation and proposes becoming leader  explains hosen s individualist policy  proposes secret negotiations to horikita  tests ayanokoji s character  explains class 1 d started with 800 class points  negotiates with her  discusses cooperation with him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p204-1\"><h3><span class=\"ttl\">Ch.5: Library meeting and strategy<\/span><span class=\"meta\">Y2V1 · p.204–242<\/span><\/h3><p class=\"setup\">Meets Horikita and Ayanokōji in the library. Reveals Class 1-D’s situation and proposes becoming leader. Explains Hōsen’s individualist policy. Proposes secret negotiations to Horikita. Tests Ayanokōji’s character. Explains Class 1-D started with 800 class points.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Negotiates with her.<span class=\"pg\">p.204–233<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Discusses cooperation with him.<span class=\"pg\">p.204–242<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p142-1\">← Before: Ch.4: Approaching Ayanokōji<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p205-1\">→ After: Nanase negotiates on behalf of Class 1-D<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p205-1","v":"y2v1","y":2,"o":16,"k":"spoken","w":"horikita-suzune housen-kazuomi ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase negotiates on behalf of class 1 d arrives alone at the library for the discussion with horikita and ayanokoji  fumbles her self introduction  starting with the masculine  boku  a detail the translation flags   i  no  that s not right  i am known as nanase tsubasa  i haven t done anything worthy of your thanks   many students have already begun taking action in accordance with hosen kun s orders   i m immensely sorry  but i m afraid i can t provide you with any specifics   an act of betrayal   our doors are always open to you  as long as you present us with at least a fixed number of private points  we ll accept the partnership without the slightest bit of hesitation   what really gets to me is the thought that this individualistic mindset might never go away  preventing us from being able to unite as a class in the future   yes    when asked if she fears hosen  at this point  i believe that approximately fifteen students would find it difficult to search for a partner on their own   hosen kun would never allow us to help you out for free  especially not now   hosen kun has not received any compensation from our classmates  upright  fearless and loyal   refuses to leak hosen s strategy  calling it betrayal  admits she fears him yet opposes his individualism for the class s future  and reveals he takes no profit  she negotiates single handedly to save the weak  negotiates the 15 pair equal cooperation proposal with her  confirms he controls class 1 d via orders  with no personal compensation  she opposes his individualist policy  treats him with respect  fixes her  same look  on him   the hidden white room agent quietly assessing her target","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p205-1\"><h3><span class=\"ttl\">Nanase negotiates on behalf of Class 1-D<\/span><span class=\"meta\">Y2V1 · p.205–214<\/span><\/h3><p class=\"setup\">Arrives alone at the library for the discussion with Horikita and Ayanokōji; fumbles her self-introduction (starting with the masculine &quot;Boku,&quot; a detail the translation flags).<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I─ No, that&#x27;s not right… I am known as Nanase Tsubasa. I haven&#x27;t done anything worthy of your thanks.&quot;<span class=\"pg\">p.208<\/span><\/li><li class=\"q spoken\">&quot;Many students have already begun taking action in accordance with Hōsen-kun&#x27;s orders.&quot;<span class=\"pg\">p.209<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m immensely sorry, but I&#x27;m afraid I can&#x27;t provide you with any specifics.&quot;<span class=\"pg\">p.209<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;an act of betrayal.&quot;<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;our doors are always open to you. As long as you present us with at least a fixed number of private points, we&#x27;ll accept the partnership without the slightest bit of hesitation.&quot;<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;What really gets to me is the thought that this individualistic mindset might never go away, preventing us from being able to unite as a class in the future.&quot;<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yes.&quot; — when asked if she fears Hōsen<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;At this point, I believe that approximately fifteen students would find it difficult to search for a partner on their own.&quot;<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Hōsen-kun would never allow us to help you out for free. Especially not now.&quot;<span class=\"pg\">p.213<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Hōsen-kun has not received any compensation from our classmates.&quot;<span class=\"pg\">p.214<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Upright, fearless and loyal — refuses to leak Hōsen&#x27;s strategy (calling it betrayal), admits she fears him yet opposes his individualism for the class&#x27;s future, and reveals he takes no profit; she negotiates single-handedly to save the weak.<span class=\"pg\">p.208–214<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Negotiates the 15-pair equal-cooperation proposal with her.<span class=\"pg\">p.208–214<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Confirms he controls Class 1-D via orders, with no personal compensation; she opposes his individualist policy.<span class=\"pg\">p.209–214<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Treats him with respect; fixes her &quot;same look&quot; on him — the hidden White Room agent quietly assessing her target.<span class=\"pg\">p.208–214<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p204-1\">← Before: Ch.5: Library meeting and strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p290-1\">→ After: Ch.6: Mediating and revealing<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p290-1","v":"y2v1","y":2,"o":16,"k":"","w":"housen-kazuomi horikita-suzune ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 6  mediating and revealing mediates between horikita and hosen  tries to stop hosen from leaving  explains nagumo s tolerance of fighting  proposes mutual trust  warns horikita about hosen s true nature  blocks hosen from stabbing ayanokoji  explains the 20 million point bounty and hosen s plan  reveals her true feelings toward ayanokoji  mediates for him  negotiates with her  explains to him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p290-1\"><h3><span class=\"ttl\">Ch.6: Mediating and revealing<\/span><span class=\"meta\">Y2V1 · p.290–335<\/span><\/h3><p class=\"setup\">Mediates between Horikita and Hōsen. Tries to stop Hōsen from leaving. Explains Nagumo’s tolerance of fighting. Proposes mutual trust. Warns Horikita about Hōsen’s true nature. Blocks Hōsen from stabbing Ayanokōji. Explains the 20-million-point bounty and Hōsen’s plan. Reveals her true feelings toward Ayanokōji.<\/p><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Mediates for him.<span class=\"pg\">p.290–331<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Negotiates with her.<span class=\"pg\">p.290–333<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Explains to him.<span class=\"pg\">p.333–335<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p205-1\">← Before: Nanase negotiates on behalf of Class 1-D<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p326-1\">→ After: Nanase stops Hōsen; reveals the 20-million bounty and her hatred<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p326-1","v":"y2v1","y":2,"o":16,"k":"spoken","w":"housen-kazuomi horikita-suzune ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase stops hosen  reveals the 20 million bounty and her hatred steps between hosen and ayanokoji as he advances with the knife  spreading her arms to block him   please don t go any further  i can t approve of your methods after all  i can t   i made the decision to lend you my strength until the very end  telling myself that it was for the good of the class   horikita senpai  working together with hosen kun has been impossible from the very beginning   that was just a ploy to get things to progress to this point   no  nothing of the sort  horikita senpai  i truly did want to join hands with you and establish a supporting relationship between our two classes   we were told that the student who manages to expel ayanokoji kiyotaka of class 2 d will receive a bulk sum of 20 million private points  that s the special exam that was given to us   for the sake of my class  of class 1 d  i chose to cooperate with hosen kun knowing full well just how awful his methods truly were   because  if the 20 million point bounty were to fall into the hands of another class  it would bring about serious ramifications for us moving forward   i  simply didn t believe a person like you would be suitable for this school  ayanokoji senpai  breaks with hosen to stop the knife  reveals the negotiation was a ploy from the start and the 20 million point bounty  and explains she cooperated to keep the bounty from another class   then reveals an unexplained personal hatred  using the masculine katakana  boku  in her final line  deliberately linking herself to ayanokoji  per the translation notes  physically stops him  declares she was wrong to accept his methods  and is brushed aside  reveals the plot and bounty to her and ayanokoji  urges them to beware other first year classes  directs open hatred at him   the white room agent s true motive remains hidden  she stays behind to explain  then leaves","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p326-1\"><h3><span class=\"ttl\">Nanase stops Hōsen; reveals the 20-million bounty and her hatred<\/span><span class=\"meta\">Y2V1 · p.326–341<\/span><\/h3><p class=\"setup\">Steps between Hōsen and Ayanokōji as he advances with the knife, spreading her arms to block him.<\/p><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Please don&#x27;t go any further! I can&#x27;t approve of your methods after all… I can&#x27;t!&quot;<span class=\"pg\">p.326<\/span><\/li><li class=\"q spoken\">&quot;I made the decision to lend you my strength until the very end, telling myself that it was for the good of the class.&quot;<span class=\"pg\">p.328<\/span><\/li><li class=\"q spoken\">&quot;Horikita-senpai, working together with Hōsen-kun has been impossible from the very beginning.&quot;<span class=\"pg\">p.328<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;That was just a ploy to get things to progress to this point.&quot;<span class=\"pg\">p.328<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;No, nothing of the sort, Horikita-senpai. I truly did want to join hands with you and establish a supporting relationship between our two classes.&quot;<span class=\"pg\">p.340<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;We were told that the student who manages to expel Ayanokōji Kiyotaka of Class 2-D will receive a bulk sum of 20 million private points. That&#x27;s the special exam that was given to us.&quot;<span class=\"pg\">p.340<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;For the sake of my class, of Class 1-D, I chose to cooperate with Hōsen-kun knowing full well just how awful his methods truly were.&quot;<span class=\"pg\">p.341<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Because, if the 20 million point bounty were to fall into the hands of another class, it would bring about serious ramifications for us moving forward.&quot;<span class=\"pg\">p.341<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I*… simply didn&#x27;t believe a person like you would be suitable for this school, Ayanokōji-senpai.&quot;<span class=\"pg\">p.341<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Breaks with Hōsen to stop the knife, reveals the negotiation was a ploy from the start and the 20-million-point bounty, and explains she cooperated to keep the bounty from another class — then reveals an unexplained personal hatred, using the masculine katakana &quot;boku&quot; in her final line (deliberately linking herself to Ayanokōji, per the translation notes).<span class=\"pg\">p.326–341<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Physically stops him, declares she was wrong to accept his methods, and is brushed aside.<span class=\"pg\">p.326–328<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Reveals the plot and bounty to her and Ayanokōji; urges them to beware other first-year classes.<span class=\"pg\">p.328–341<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Directs open hatred at him — the White Room agent&#x27;s true motive remains hidden; she stays behind to explain, then leaves.<span class=\"pg\">p.341<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p290-1\">← Before: Ch.6: Mediating and revealing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p344-1\">→ After: Epilogue: Short story<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p344-1","v":"y2v1","y":2,"o":16,"k":"","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa epilogue  short story irons out the agreement with horikita  observes ayanokoji on the school grounds  approaches him  meets him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p344-1\"><h3><span class=\"ttl\">Epilogue: Short story<\/span><span class=\"meta\">Y2V1 · p.344, 364–365<\/span><\/h3><p class=\"setup\">Irons out the agreement with Horikita. Observes Ayanokōji on the school grounds. Approaches him.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Meets him.<span class=\"pg\">p.344, 364–365<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p326-1\">← Before: Nanase stops Hōsen; reveals the 20-million bounty and her hatred<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p364-1\">→ After: Short story: &quot;What is Reflected in Her Eyes&quot;<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p364-1","v":"y2v1","y":2,"o":16,"k":"narration","w":"ayanokouji-kiyotaka housen-kazuomi nanase-tsubasa","q":"nanase tsubasa short story   what is reflected in her eyes  after leaving the dorm  spots ayanokoji approaching two class 1 a girls and decides to intercept him first  running to match his pace   good morning  ayanokouji senpai   i definitely think i managed a perfect smile   ayanokouji senpai s presence is unusually peculiar   i will force him to deepen his relationship with class 1 d   you can t judge people by their apperances  from her own viewpoint  deliberately engineers the chance morning encounter  judging ayanokoji an absentminded sharpened blade whose good or evil nature is all that matters to her  holds strongly to the belief that appearances can t tell a person s worth  the corpus prints  apperances  and notes his d class cooperation proposal is exactly what she d wanted   the white room agent manipulating the meeting  deliberately approaches him to draw him into class 1 d  he unexpectedly proposes the very cooperation she sought  she follows him to stop his outbursts  feeling powerless","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p364-1\"><h3><span class=\"ttl\">Short story: &quot;What is Reflected in Her Eyes&quot;<\/span><span class=\"meta\">Y2V1 · p.364–367<\/span><\/h3><p class=\"setup\">After leaving the dorm, spots Ayanokōji approaching two Class 1-A girls and decides to intercept him first, running to match his pace.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;Good morning, Ayanokouji-senpai.&quot;<span class=\"pg\">p.364<\/span><\/li><li class=\"q narration\">&quot;I definitely think I managed a perfect smile.&quot;<span class=\"pg\">p.365<\/span><\/li><li class=\"q narration\">&quot;Ayanokouji-senpai&#x27;s presence is unusually peculiar.&quot;<span class=\"pg\">p.365<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;I will force him to deepen his relationship with class 1-D&quot;<span class=\"pg\">p.366<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;You can&#x27;t judge people by their apperances.&quot;<span class=\"pg\">p.367<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> From her own viewpoint, deliberately engineers the chance morning encounter, judging Ayanokōji an absentminded sharpened blade whose good-or-evil nature is all that matters to her; holds strongly to the belief that appearances can&#x27;t tell a person&#x27;s worth (the corpus prints &quot;apperances&quot;) and notes his D-Class cooperation proposal is exactly what she&#x27;d wanted — the White Room agent manipulating the meeting.<span class=\"pg\">p.364–367<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Deliberately approaches him to draw him into Class 1-D; he unexpectedly proposes the very cooperation she sought.<span class=\"pg\">p.364–367<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> She follows him to stop his outbursts, feeling powerless.<span class=\"pg\">p.365<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p344-1\">← Before: Epilogue: Short story<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p368-1\">→ After: Short story: &quot;The Voice in My Heart&quot;<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p368-1","v":"y2v1","y":2,"o":16,"k":"narration","w":"ayanokouji-kiyotaka horikita-suzune nanase-tsubasa","q":"nanase tsubasa short story   the voice in my heart  after horikita leaves the library  probes ayanokoji about how he ll convince hosen  then turns the question on him   that  i don t have a problem answering that question but only if  if you can tell me about you   what  kind of person are you  senpai   what you want to know isn t about her relationship with me  it seems   yes  i think you are a wicked and a filthy human being  ayanokouji senpai   as far as i can see  you look like a regular human being  ayanokouji senpai  boldly voices her belief that he is a wicked  filthy human being yet looks like a regular human   testing him about his true nature  good or evil  retreats when she fears she s come too close  while noting he seemed to understand exactly what she wanted to ask  uses the masculine  boku   katakana  hinting at her link to him  presses him on what kind of person he is  he sees through her intended question  admires her and wishes to become as splendid as her by next year","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p368-1\"><h3><span class=\"ttl\">Short story: &quot;The Voice in My Heart&quot;<\/span><span class=\"meta\">Y2V1 · p.368–369<\/span><\/h3><p class=\"setup\">After Horikita leaves the library, probes Ayanokōji about how he&#x27;ll convince Hōsen, then turns the question on him.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;That… I don&#x27;t have a problem answering that question but only if, if you can tell me about you.&quot;<span class=\"pg\">p.368<\/span><\/li><li class=\"q narration\">&quot;What— kind of person are you, senpai?&quot;<span class=\"pg\">p.368<\/span><\/li><li class=\"q narration\">&quot;What you want to know isn&#x27;t about her relationship with me, it seems.&quot;<span class=\"pg\">p.369<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;Yes, I think you are a wicked and a filthy human being, Ayanokouji-senpai.&quot;<span class=\"pg\">p.369<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;As far as I can see, you look like a regular human being, Ayanokouji-senpai.&quot;<span class=\"pg\">p.369<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Boldly voices her belief that he is a wicked, filthy human being yet looks like a regular human — testing him about his true nature (good or evil); retreats when she fears she&#x27;s come too close, while noting he seemed to understand exactly what she wanted to ask; uses the masculine &quot;boku&quot; (katakana), hinting at her link to him.<span class=\"pg\">p.368–369<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Presses him on what kind of person he is; he sees through her intended question.<span class=\"pg\">p.368–369<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Admires her and wishes to become as splendid as her by next year.<span class=\"pg\">p.368<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p364-1\">← Before: Short story: &quot;What is Reflected in Her Eyes&quot;<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v2-p6-1","v":"y2v2","y":2,"o":17,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa full volume appears in this volume","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v2-p6-1\"><h3><span class=\"ttl\">Full volume<\/span><span class=\"meta\">Y2V2 · p.6-354<\/span><\/h3><p class=\"setup\">Appears in this volume.<\/p><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p7-1","v":"y2v3","y":2,"o":18,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa full volume appears in this volume","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p7-1\"><h3><span class=\"ttl\">Full volume<\/span><span class=\"meta\">Y2V3 · p.7-368<\/span><\/h3><p class=\"setup\">Appears in this volume.<\/p><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p5-1","v":"y2v4","y":2,"o":19,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa full volume appears in this volume","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p5-1\"><h3><span class=\"ttl\">Full volume<\/span><span class=\"meta\">Y2V4 · p.5-284<\/span><\/h3><p class=\"setup\">Appears in this volume.<\/p><\/article>"},{"i":"sc-nanase-tsubasa-y2v4_5-p10-1","v":"y2v4.5","y":2,"o":20,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa full volume appears in this volume","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4_5-p10-1\"><h3><span class=\"ttl\">Full volume<\/span><span class=\"meta\">Y2V4.5 · p.10-290<\/span><\/h3><p class=\"setup\">Appears in this volume.<\/p><\/article>"},{"i":"sc-nanase-tsubasa-y2v6-p11-1","v":"y2v6","y":2,"o":22,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa full volume appears in this volume","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v6-p11-1\"><h3><span class=\"ttl\">Full volume<\/span><span class=\"meta\">Y2V6 · p.11-346<\/span><\/h3><p class=\"setup\">Appears in this volume.<\/p><\/article>"},{"i":"sc-nanase-tsubasa-y2v7-p7-1","v":"y2v7","y":2,"o":23,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa full volume appears in this volume","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v7-p7-1\"><h3><span class=\"ttl\">Full volume<\/span><span class=\"meta\">Y2V7 · p.7-207<\/span><\/h3><p class=\"setup\">Appears in this volume.<\/p><\/article>"},{"i":"sc-nanase-tsubasa-y2v8-p11-1","v":"y2v8","y":2,"o":24,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa full volume appears in this volume","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v8-p11-1\"><h3><span class=\"ttl\">Full volume<\/span><span class=\"meta\">Y2V8 · p.11-208<\/span><\/h3><p class=\"setup\">Appears in this volume.<\/p><\/article>"},{"i":"sc-nanase-tsubasa-y2v9-p8-1","v":"y2v9","y":2,"o":25,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa full volume appears in this volume","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v9-p8-1\"><h3><span class=\"ttl\">Full volume<\/span><span class=\"meta\">Y2V9 · p.8-225<\/span><\/h3><p class=\"setup\">Appears in this volume.<\/p><\/article>"},{"i":"sc-nanase-tsubasa-y2v9_5-p10-1","v":"y2v9.5","y":2,"o":26,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa full volume appears in this volume","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v9_5-p10-1\"><h3><span class=\"ttl\">Full volume<\/span><span class=\"meta\">Y2V9.5 · p.10-219<\/span><\/h3><p class=\"setup\">Appears in this volume.<\/p><\/article>"},{"i":"sc-nanase-tsubasa-y2v11-p11-1","v":"y2v11","y":2,"o":30,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa full volume appears in this volume","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v11-p11-1\"><h3><span class=\"ttl\">Full volume<\/span><span class=\"meta\">Y2V11 · p.11-223<\/span><\/h3><p class=\"setup\">Appears in this volume.<\/p><\/article>"},{"i":"sc-nanase-tsubasa-y2v12_5-p148-1","v":"y2v12.5","y":2,"o":32,"k":"","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 9 mentioned appears in ch 9  appears in this volume","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v12_5-p148-1\"><h3><span class=\"ttl\">Ch.9<\/span><span class=\"meta\">Y2V12.5 · p.148-176<\/span><\/h3><p class=\"setup\">Mentioned/appears in Ch.9.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Appears in this volume.<span class=\"pg\">p.148-176<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y3v1-p225-1","v":"y3v1","y":3,"o":33,"k":"spoken","w":"tsukishiro horikita-suzune ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa epilogue   depth read  nanase s secret call is with horikita in the student council room when the three eavesdroppers arrive  after horikita leaves  takes a phone call   it s not like that  it s all thanks to your precise instructions  president horikita   yes  i definitely want to graduate from class a  however  as long as i can finish my school life safely  that would be the best outcome for me   we agreed not to make any unnecessary calls  didn t we  tsukishiro san   i ll continue to monitor ayanokouji senpai for another year   senpai  what might you guys be doing in a place like this  is revealed to be in contact with tsukishiro  monitoring ayanokoji  possessing two phones against school rules  and noticing the eavesdroppers  polite and diligent in public  secretly duplicitous   plays the loyal student council member while carrying out tsukishiro s surveillance  calls him and reports on monitoring ayanokoji  ishigami kyou and a notable first year  works alongside her in the student council and praises her instructions  is monitoring him on tsukishiro s orders","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v1-p225-1\"><h3><span class=\"ttl\">Epilogue — depth read: Nanase&#x27;s secret call<\/span><span class=\"meta\">Y3V1 · p.225–287<\/span><\/h3><p class=\"setup\">Is with Horikita in the student council room when the three eavesdroppers arrive; after Horikita leaves, takes a phone call.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;It&#x27;s not like that. It&#x27;s all thanks to your precise instructions, President Horikita.&quot;<span class=\"pg\">p.242<\/span><\/li><li class=\"q spoken\">&quot;Yes, I definitely want to graduate from Class A. However, as long as I can finish my school life safely, that would be the best outcome for me.&quot;<span class=\"pg\">p.242<\/span><\/li><li class=\"q spoken\">&quot;We agreed not to make any unnecessary calls, didn&#x27;t we, Tsukishiro-san?&quot;<span class=\"pg\">p.243<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ll continue to monitor Ayanokouji-senpai for another year.&quot;<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Senpai, what might you guys be doing in a place like this?&quot;<span class=\"pg\">p.247<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Is revealed to be in contact with Tsukishiro, monitoring Ayanokōji, possessing two phones against school rules, and noticing the eavesdroppers.<span class=\"pg\">p.243–247<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Polite and diligent in public, secretly duplicitous — plays the loyal student council member while carrying out Tsukishiro&#x27;s surveillance.<span class=\"pg\">p.241–247<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Calls him and reports on monitoring Ayanokōji, Ishigami Kyou and a notable first-year.<span class=\"pg\">p.243–246<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Works alongside her in the student council and praises her instructions.<span class=\"pg\">p.241–243<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is monitoring him on Tsukishiro&#x27;s orders.<span class=\"pg\">p.246<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p10-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"tsukishiro ayanokouji-kiyotaka ayanokouji-atsuomi nanase-tsubasa","q":"nanase tsubasa prologue   depth read  tsukishiro s offer sits beside the unconscious matsuo eiichirou in his hospital room  overwhelmed with regret   how did it come to this   if i d noticed something was wrong with eiichirou kun  this wouldn t have happened   i have brought you an opportunity to exact your revenge   attending anhs is the only way to get close to your target   my apologies  my name is tsukishiro  i ve been well acquainted with you and matsuo kun sleeping here  since you were children   you must mix lies with the truth  her goal has shifted from revenge   to help ayanokoji so he won t become a  pure evil  who creates more victims like eiichirou  is recruited by him to get close to ayanokoji in exchange for revenge  is tasked with approaching him as an insignificant being  now wants to save him  holds him responsible for cornering eiichirou   the true target of her revenge  tsukishiro s mention of  shirogane san  proves he knew nanase since childhood  eiichirou is in a vegetative state   a  prolonged disturbance of consciousness","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p10-1\"><h3><span class=\"ttl\">Prologue — depth read: Tsukishiro&#x27;s offer<\/span><span class=\"meta\">Y3V2 · p.10–12<\/span><\/h3><p class=\"setup\">Sits beside the unconscious Matsuo Eiichirou in his hospital room, overwhelmed with regret.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;How did it come to this—&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\">&quot;If I&#x27;d noticed something was wrong with Eiichirou-kun, this wouldn&#x27;t have happened.&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;I have brought you an opportunity to exact your revenge.&quot;<span class=\"pg\">p.10<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Attending ANHS is the only way to get close to your target—&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;My apologies. My name is Tsukishiro. I&#x27;ve been well acquainted with you and Matsuo-kun sleeping here, since you were children.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You must mix lies with the truth.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her goal has shifted from revenge — to help Ayanokōji so he won&#x27;t become a &quot;pure evil&quot; who creates more victims like Eiichirou.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Is recruited by him to get close to Ayanokōji in exchange for revenge.<span class=\"pg\">p.10–12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is tasked with approaching him as an insignificant being; now wants to save him.<span class=\"pg\">p.11–12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> Holds him responsible for cornering Eiichirou — the true target of her revenge.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsukishiro&#x27;s mention of &quot;Shirogane-san&quot; proves he knew Nanase since childhood.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Eiichirou is in a vegetative state — a &quot;prolonged disturbance of consciousness.&quot;<span class=\"pg\">p.10<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p10-2\">→ After: Nanase at Eiichirou&#x27;s bedside; Tsukishiro&#x27;s offer<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p10-2","v":"y3v2","y":3,"o":34,"k":"narration spoken","w":"tsukishiro nanase-tsubasa","q":"nanase tsubasa nanase at eiichirou s bedside  tsukishiro s offer sits beside matsuo eiichirou in his hospital room  murmuring  how did it come to this  as he lies in a vegetative state   how did it come to this   yes  if i  if i d noticed something was wrong with eiichirou kun  this wouldn t have happened  no  i never would have let something like this happen  eiichirou suffers from a  prolonged disturbance of consciousness    a vegetative state  he can open his eyes and breathe but isn t conscious or responsive  doctors gave a slim chance of recovery within weeks or months   you cannot survive in this world on kindness alone  no  in fact  you ll be preyed upon by fiends so wicked they are beyond salvation   the world works on give and take  you understand that  yes   yes  i am grateful for your considerable support  after visiting hospital after hospital  tsukishiro was the one who found a place that would accept eiichirou  thirty minutes later and he might not have survived   what is it you want me to do   i have brought you an opportunity to exact your revenge   i will teach you how to get close to the person you should take revenge on  he offers her revenge in exchange for getting close to a target","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p10-2\"><h3><span class=\"ttl\">Nanase at Eiichirou&#x27;s bedside; Tsukishiro&#x27;s offer<\/span><span class=\"meta\">Y3V2 · p.10–11<\/span><\/h3><p class=\"setup\">Sits beside Matsuo Eiichirou in his hospital room, murmuring &quot;How did it come to this—&quot; as he lies in a vegetative state.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;HOW DID IT come to this—&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;You cannot survive in this world on kindness alone. No, in fact, you&#x27;ll be preyed upon by fiends so wicked they are beyond salvation—&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;The world works on give-and-take. You understand that, yes?&quot;<span class=\"pg\">p.10<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;...Yes... If I... If I&#x27;d noticed something was wrong with Eiichirou-kun, this wouldn&#x27;t have happened, no... I never would have let something like this happen...&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Eiichirou suffers from a &quot;prolonged disturbance of consciousness&quot; — a vegetative state: he can open his eyes and breathe but isn&#x27;t conscious or responsive; doctors gave a slim chance of recovery within weeks or months.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yes. I am grateful for your considerable support.&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> After visiting hospital after hospital, Tsukishiro was the one who found a place that would accept Eiichirou; thirty minutes later and he might not have survived.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;What is it you want me to do?&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I have brought you an opportunity to exact your revenge.&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I will teach you how to get close to the person you should take revenge on.&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> He offers her revenge in exchange for getting close to a target.<span class=\"pg\">p.10–11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p10-1\">← Before: Prologue — depth read: Tsukishiro&#x27;s offer<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p11-1\">→ After: Learning the target; Tsukishiro&#x27;s true nature<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p11-1","v":"y3v2","y":3,"o":34,"k":"narration spoken","w":"tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa learning the target  tsukishiro s true nature tsukishiro places an application form and photograph on the portable table   what is this   attending anhs is the only way to get close to your target   i realize i haven t asked your name  who are you   my apologies  my name is tsukishiro  i ve been well acquainted with you and matsuo kun sleeping here  since you were children   i ve seen plenty of adults approach me  pretending to know things when they really know nothing   is shirogane san doing well  the name shirogane makes her body react unconsciously  betraying her feigned composure   he knew them since childhood  and she instantly understands he is telling the truth   you re not evil  but the inhabitants of the world i live in are nothing but evil   you re ordinary  yet excellent  ordinary  yet immature  ordinary  yet talented   you re tsukishiro san  you said  is this boy connected to that evil   he is ayanokouji kiyotaka  a key figure who will lead you to the target of your revenge  tsukishiro s mention of shirogane    she took good care of me when i was young    reveals he knew nanase and eiichirou since childhood  shirogane is not on the roster  identified in the photograph as the key figure leading to her revenge target","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p11-1\"><h3><span class=\"ttl\">Learning the target; Tsukishiro&#x27;s true nature<\/span><span class=\"meta\">Y3V2 · p.11–12<\/span><\/h3><p class=\"setup\">Tsukishiro places an application form and photograph on the portable table.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;Attending ANHS is the only way to get close to your target—&quot;<span class=\"pg\">p.11<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;My apologies. My name is Tsukishiro. I&#x27;ve been well acquainted with you and Matsuo-kun sleeping here, since you were children.&quot;<span class=\"pg\">p.11<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;Is Shirogane-san doing well?&quot;<span class=\"pg\">p.11<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;What is this...?&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;...I realize I haven&#x27;t asked your name... Who are you?&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I&#x27;ve seen plenty of adults approach me, pretending to know things when they really know nothing.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> The name Shirogane makes her body react unconsciously, betraying her feigned composure — he knew them since childhood, and she instantly understands he is telling the truth.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;re not evil. But the inhabitants of the world I live in are nothing but evil.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;re ordinary, yet excellent. Ordinary, yet immature. Ordinary, yet talented.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;You&#x27;re Tsukishiro-san, you said. Is this boy connected to that evil?&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;He is Ayanokouji Kiyotaka, a key figure who will lead you to the target of your revenge.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsukishiro&#x27;s mention of Shirogane — &quot;she took good care of me when I was young&quot; — reveals he knew Nanase and Eiichirou since childhood (Shirogane is not on the roster).<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Identified in the photograph as the key figure leading to her revenge target.<span class=\"pg\">p.11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p10-2\">← Before: Nanase at Eiichirou&#x27;s bedside; Tsukishiro&#x27;s offer<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p12-1\">→ After: Accepting the mission; the motive shifts<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p12-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"tsukishiro nanase-tsubasa","q":"nanase tsubasa accepting the mission  the motive shifts  that boy  though inorganic  has outstanding  refined instincts  if you approach him carelessly  he will easily see through you   then  what should i do   you must mix lies with the truth   he will naturally be suspicious of you  but he won t delve too deeply  that is because he will recognize you as an insignificant being   let me ask one last thing  why me   it is because you are in a perfect position  neither clearly on one side  nor the other  she nods without a pause   at that time her heart was set on revenge against ayanokouji atsuomi  the one who cornered eiichirou  her motive has since shifted  she now wants to help ayanokouji senpai  believing that if he graduates as he is  he will walk a path of  pure evil  and create more victims like eiichirou   so  knowing that predicament firsthand  she must stop it  shirogane is not on the roster   tsukishiro s remark is recorded here  not as a  rel  to a non existent id","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p12-1\"><h3><span class=\"ttl\">Accepting the mission; the motive shifts<\/span><span class=\"meta\">Y3V2 · p.12<\/span><\/h3><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;That boy, though inorganic, has outstanding, refined instincts. If you approach him carelessly, he will easily see through you.&quot;<span class=\"pg\">p.12<\/span><\/li><li class=\"q spoken\">&quot;Then, what should I do?&quot;<span class=\"pg\">p.12<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;You must mix lies with the truth.&quot;<span class=\"pg\">p.12<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;He will naturally be suspicious of you, but he won&#x27;t delve too deeply. That is because he will recognize you as an insignificant being.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Let me ask one last thing. Why me?&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It is because you are in a perfect position. Neither clearly on one side, nor the other.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> She nods without a pause — at that time her heart was set on revenge against Ayanokouji Atsuomi, the one who cornered Eiichirou.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her motive has since shifted: she now wants to help Ayanokouji-senpai, believing that if he graduates as he is, he will walk a path of &quot;pure evil&quot; and create more victims like Eiichirou — so, knowing that predicament firsthand, she must stop it.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Shirogane is not on the roster — Tsukishiro&#x27;s remark is recorded here, not as a `[rel:]` to a non-existent id.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p11-1\">← Before: Learning the target; Tsukishiro&#x27;s true nature<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p66-1\">→ After: Ch.3 — depth read: Nanase and the first-year fight<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p66-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"horikita-suzune nanase-tsubasa","q":"nanase tsubasa ch 3   depth read  nanase and the first year fight works with horikita in the student council room on the case of first years kusanagi and maki   you mean their pride was wounded because they lost a two on one fight  it s not out of the question  but would they really be that tight lipped about it   of course  student council president  but being the president is a lot of work  isn t it  you re amazing  horikita senpai   no mediocre  even so  i think that s fine  a mediocre horikita senpai isn t bad at all   w wha  i i m so sorry  i think student council president horikita is very admirable  helpful but awkward   blurted out the honest view that being mediocre is fine and panicked  trying to smooth it over  assists her in the investigation and is asked to help uncover the truth  the two first years kusanagi minato and maki yuuma got into a fight  neither would report it  hinting a third party  possibly a girl  was involved","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p66-1\"><h3><span class=\"ttl\">Ch.3 — depth read: Nanase and the first-year fight<\/span><span class=\"meta\">Y3V2 · p.66–125<\/span><\/h3><p class=\"setup\">Works with Horikita in the student council room on the case of first-years Kusanagi and Maki.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;You mean their pride was wounded because they lost a two-on-one fight? It&#x27;s not out of the question, but would they really be that tight-lipped about it?&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\">&quot;Of course, Student Council President. But being the president is a lot of work, isn&#x27;t it? You&#x27;re amazing, Horikita-senpai.&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\">&quot;No—mediocre. Even so, I think that&#x27;s fine. A mediocre Horikita-senpai isn&#x27;t bad at all.&quot;<span class=\"pg\">p.88<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;W-Wha—!? I-I&#x27;m so sorry! I think Student Council President Horikita is very admirable!&quot;<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Helpful but awkward — blurted out the honest view that being mediocre is fine and panicked, trying to smooth it over.<span class=\"pg\">p.87–88<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Assists her in the investigation and is asked to help uncover the truth.<span class=\"pg\">p.85–88<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The two first-years Kusanagi Minato and Maki Yuuma got into a fight; neither would report it, hinting a third party (possibly a girl) was involved.<span class=\"pg\">p.86<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p12-1\">← Before: Accepting the mission; the motive shifts<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p211-1\">→ After: Ch.7 — depth read: Nanase works the White Room angle<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p211-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"shiraishi-asuka tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 7   depth read  nanase works the white room angle meets shiraishi back to back in a quiet restaurant  having called her out   have i kept you waiting   why is that   then why have you started to close the distance now   i am from that side   at least give me some information  please  just disclose the names of your associates   that if i am expelled before ayanokouji senpai s fate is decided  things may very well head in a direction that shirogane sensei would not desire  cautious and probing   arranged a covert meeting  tries to read shiraishi through emphases and emphasized names  and aligns herself with tsukishiro s anti ayanokoji faction  demands her cooperation intelligence  is refused  and warns her of consequences if expelled  reveals she is aligned with his faction  that side superiors  is working against him  refers to him as  ayanokouji senpai  cites  shirogane sensei  in her warning   a name tied to her past  not on the roster","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p211-1\"><h3><span class=\"ttl\">Ch.7 — depth read: Nanase works the White Room angle<\/span><span class=\"meta\">Y3V2 · p.211–230<\/span><\/h3><p class=\"setup\">Meets Shiraishi back-to-back in a quiet restaurant, having called her out.<\/p><p class=\"with\">with <a href=\"shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Have I kept you waiting?&quot;<span class=\"pg\">p.226<\/span><\/li><li class=\"q spoken\">&quot;Why...is that?&quot;<span class=\"pg\">p.228<\/span><\/li><li class=\"q spoken\">&quot;Then why have you started to close the distance now?&quot;<span class=\"pg\">p.229<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I am from that side.&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;At least give me some information... Please, just disclose the names of your associates.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That if I am expelled before Ayanokouji-senpai&#x27;s fate is decided... things may very well head in a direction that Shirogane-sensei would not desire.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cautious and probing — arranged a covert meeting, tries to read Shiraishi through emphases and emphasized names, and aligns herself with Tsukishiro&#x27;s anti-Ayanokōji faction.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Demands her cooperation/intelligence; is refused, and warns her of consequences if expelled.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Reveals she is aligned with his faction (&quot;that side&quot;/&quot;superiors&quot;).<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is working against him; refers to him as &quot;Ayanokouji-senpai.&quot;<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Cites &quot;Shirogane-sensei&quot; in her warning — a name tied to her past (not on the roster).<span class=\"pg\">p.230<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p66-1\">← Before: Ch.3 — depth read: Nanase and the first-year fight<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p226-1\">→ After: Nanase&#x27;s secret meeting: asking Shiraishi to expel Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p226-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"shiraishi-asuka ayanokouji-kiyotaka tsukishiro hashimoto-masayoshi morishita-ai nanase-tsubasa","q":"nanase tsubasa nanase s secret meeting  asking shiraishi to expel ayanokoji sits back to back with shiraishi in a quiet restaurant  having contacted her in violation of the rules   are you really sure this was the right place to meet   it s true that it s easier to talk since there are few customers  but on the flip side  that means we inevitably stand out   i want to get ayanokouji senpai expelled  as soon as possible  and at a time he can t predict   then why have you started to close the distance now   i will take action while ayanokouji senpai is still within reach   at least give me some information  please  just disclose the names of your associates  cautious and probing   uses a back to back meeting  deliberately emphasizes  nishikawa  to read shiraishi s reaction  admits carelessness with the second phone  and grows impatient in her goal to expel ayanokoji  aligns herself with tsukishiro s anti ayanokoji faction  tries to recruit her  refused  but leaves with a warning about shirogane  wants him expelled as soon as possible  her  superior  in the anti ayanokoji faction  recorded via shiraishi s line  shiraishi silenced him after he witnessed nanase s second phone  likewise silenced","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p226-1\"><h3><span class=\"ttl\">Nanase&#x27;s secret meeting: asking Shiraishi to expel Ayanokōji<\/span><span class=\"meta\">Y3V2 · p.226–230<\/span><\/h3><p class=\"setup\">Sits back-to-back with Shiraishi in a quiet restaurant, having contacted her in violation of the rules.<\/p><p class=\"with\">with <a href=\"shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"morishita-ai.html\">Morishita Ai<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Are you really sure this was the right place to meet?&quot;<span class=\"pg\">p.226<\/span><\/li><li class=\"q spoken\">&quot;It&#x27;s true that it&#x27;s easier to talk since there are few customers, but on the flip side, that means we inevitably stand out.&quot;<span class=\"pg\">p.227<\/span><\/li><li class=\"q spoken\">&quot;I want to get Ayanokouji-senpai expelled. As soon as possible, and at a time he can&#x27;t predict.&quot;<span class=\"pg\">p.228<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Then why have you started to close the distance now?&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I will take action while Ayanokouji-senpai is still within reach.&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;At least give me some information... Please, just disclose the names of your associates.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cautious and probing — uses a back-to-back meeting, deliberately emphasizes &quot;Nishikawa&quot; to read Shiraishi&#x27;s reaction, admits carelessness with the second phone, and grows impatient in her goal to expel Ayanokōji; aligns herself with Tsukishiro&#x27;s anti-Ayanokōji faction.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Tries to recruit her; refused, but leaves with a warning about Shirogane.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Wants him expelled as soon as possible.<span class=\"pg\">p.228–229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Her &quot;superior&quot; in the anti-Ayanokōji faction (recorded via Shiraishi&#x27;s line).<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Shiraishi silenced him after he witnessed Nanase&#x27;s second phone.<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Likewise silenced.<span class=\"pg\">p.228<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p211-1\">← Before: Ch.7 — depth read: Nanase works the White Room angle<\/button><\/div><\/article>"}];
